import * as React from 'react';
import { renderToString } from 'react-dom/server';

const wanted = (process.env.CHECK_LANG ?? 'en') as string;
(globalThis as any).window = { localStorage: { getItem: () => wanted, setItem() {} } };

const { App } = await import('./App');
const html = renderToString(<App />);
const strip = (s: string) => s.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ');
const text = strip(html);
const probes = ['Localized application', 'Локализованное приложение', 'Previous', 'Предыдущая', 'Save', 'Сохранить'];
